select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'catalog_work_descriptions:33' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987147009 and t.language='nl')='{"text":"Nina''s vader neemt als postbode een brief mee die aan het Ministerie van Oplossingen is gericht. De jonge afzender Ruben vraagt om hulp omdat hij wordt gepest. Nina denkt dat zo''n ministerie niet bestaat en besluit samen met haar vriendin Alfa zelf iets te doen. Via Ruben en zijn oude buurvrouw ontdekt zij echter een onverwachte voorgeschiedenis. Misschien kan het verdwenen ministerie opnieuw beginnen. Daarvoor moeten de kinderen anderen helpen zonder dat de verkeerde mensen achter hun plannen en hun geheim komen.","work_id":987147009,"evidence":[{"note":"Retain Work2332 Het ministerie van Oplossingen / Sanne Rooseboom; exact Dutch Het ministerie van Oplossingen ISBN 9789000351091 Hardcover. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-031.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p401624005","http://data.bibliotheken.nl/id/nbt/p427566363","http://data.bibliotheken.nl/id/nbt/p435172093","http://data.bibliotheken.nl/id/nbt/p413917282","http://data.bibliotheken.nl/id/nbt/p437822737"],"reference":"work:2332","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-031.json","sources":["https://openlibrary.org/works/OL24484502W","https://data.bibliotheken.nl/id/nbt/p401624005","https://data.bibliotheken.nl/id/nbt/p427566363","http