70W","https://data.bibliotheken.nl/id/nbt/p435375210"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789044545418","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15173038,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:35:36.997Z","editionKey":"/books/OL61369518M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987247015,"bound_title":"Station Tokio Ueno","reviewed_at":"2026-11-03T09:35:36.993+00:00","bound_isbn13":"9789044545418","evidence_url":"https://data.bibliotheken.nl/id/nbt/p435375210","review_batch":"nl-scale-20261102-048","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987347012}'::jsonb as exact union all select 'catalog_work_descriptions:39' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987147015 and t.language='nl')='{"text":"In Vitoria worden opnieuw moorden gepleegd die herinneren aan een reeks van twintig jaar eerder. De veroordeelde archeoloog van toen staat op het punt vrij te komen, maar bevindt zich nog in gevangenschap. Profiler Unai López de Ayala probeert te voorkomen dat er meer slachtoffers vallen. Zijn eigen verleden maakt afstand houden moeilijk, net als de gespannen verhouding met zijn leidinggevende Alba. Het onderzoek verbindt hedendaagse misdaad met archeologie, plaatselijke overleveringen en familiegeheimen die niet vanzelf duidelijk maken wie achter de nieuwe doden zit.","work_id":987147015,"evidence":[{"note":"Retain Work3548 El silencio de la ciudad blanca / Eva García Sáenz